export function laCodeUrl(article: keyof typeof laCivilCode) {
  return `https://www.legis.la.gov/legis/Law.aspx?d=${laCivilCode[article]}`;
}

type Choice = [text: string, feedback: string];

// Every call below is an independently authored exercise. The helper only lays out
// answer positions and common metadata. It does not generate or vary scenarios.
const FREE_SCENARIO_IDS = new Set([9,10,11,29,30,31,56,57,58,81,82,83,109,110,129,130,146,147,164,165,182,183,194,195]);

function q(
  number: number, study: string, article: keyof typeof laCivilCode, text: string,
  answer: string, why: string, wrong: [Choice, Choice, Choice],
  scenario?: { id: string; text: string },
): LaRow {
  const position = number % 4;
  const choices: Choice[] = [...wrong];
  choices.splice(position, 0, [answer, why]);
  return {
    id: `la-${String(number).padStart(3, "0")}`, study,
    topic: study === "acts" ? "acknowledgments" : "prohibited-acts",
    difficulty: scenario ? "hard" : "medium", free: FREE_SCENARIO_IDS.has(number),
    text, options: choices.map(([option]) => option) as LaRow["options"],
    correct: position as LaRow["correct"], why,
    miss: choices.map(([, feedback]) => feedback) as LaRow["miss"],
    source: `Louisiana Civil Code art. ${article}, ${laCodeUrl(article)}, verified 2026-11-12`,
    scenario_id: scenario?.id, scenario_text: scenario?.text,
  };
}

